from pathlib import Path
import hashlib,json,datetime,subprocess,sys
R=Path(__file__).resolve().parents[1];H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
subprocess.run([sys.executable,str(R/'tools/check_ui_only_v14.py')],check=True)
paths=[R/'web/index.html']+[p for root in ['web/src','web/public']for p in(R/root).rglob('*')if p.is_file()]
rows=[{'path':str(p.relative_to(R)),'bytes':p.stat().st_size,'sha256':H(p)}for p in sorted(paths)]
tree=hashlib.sha256(''.join(x['path']+'\0'+x['sha256']+'\n'for x in sorted(rows,key=lambda x:x['path'])).encode()).hexdigest()
anchors=['dist/malabar-hot-coast.html','dist/game.bundle.js','dist/v14-ui-preview.html','dist/v14-ui-frame.html','web/package.json','web/package-lock.json','web/build-standalone.mjs','web/build-ui-preview.mjs','tests/v14/full_gate.log','tests/v14/build.log','tests/v14/final_gate_receipt.json','tests/ui_audit_v14/r2/ACCEPTANCE.md','tests/ui_audit_v14/LEAD_R2_RENDER_REVIEW.md','tests/ui_audit_v14/independent_final/v14_independent_r2_audit.zip','tests/ui_audit_v14/protected_v13_manifest.json','tests/ui_audit_v14/INDEPENDENT_STATE_CONTRACTS.md','tests/recovery/standalone_integrity.json','tests/recovery/native_metadata_final.json','tests/recovery/runtime_payload_audit.json','assets/cars/silver_refinement/freeze.json','assets/showroom/loft_freeze.json']
report={'candidate':'MALABAR V14 candidate1','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'Source/controller and exact four-viewport CSS preview gates passed; full WebGL, native touch/focus, human driving and audio listening acceptance remain separate.','base':'Frozen V13 Sites25, runtime tree dc12932f7f43d0c3940c90d73001fc3256bb4123670eac293f670713b45fbfd5','intended_runtime_changes':['web/index.html','web/src/main.js','web/src/style.css'],'runtime_tree_sha256':tree,'tree_algorithm':'SHA256 of sorted relative-path + NUL + file SHA256 + newline','runtime_files':rows,'anchors':{n:{'bytes':(R/n).stat().st_size,'sha256':H(R/n)}for n in anchors},'save_boundary':'UI-only V14 retains exact V13 garage/story storage modules, namespaces and data; no new migration or ownership/economy change.','limits':['Arcade physics, original stylized car interpretations, not engineering simulation','Existing V13 three-chapter story and cinematic mechanics unchanged','No multiplayer activation or new online currency authority','Interface screenshots and keyboard tests do not prove GPU, human handling, audio or native touch acceptance'],'license':'Approved forward-only original-asset wording correction retained; required OSM/Three/font/dependency notices preserved. No history rewrite or revocation claim.'}
(R/'tests/release').mkdir(parents=True,exist_ok=True)
(R/'tests/release/V14_RELEASE.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'intended_runtime_changes':['web/index.html','web/src/main.js','web/src/style.css'],'runtime_tree_sha256':tree,'files':len(rows),'standalone':report['anchors']['dist/malabar-hot-coast.html']},indent=2))
